-- seed.sql generated by data-ingest (do not edit by hand)
-- Compatible with PostgreSQL and SQLite.

BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS platforms (
    id TEXT PRIMARY KEY,
    sku TEXT NOT NULL,
    name TEXT NOT NULL,
    category TEXT, -- PlatformCategory, NULL in legacy seeds
    plate_cuts TEXT NOT NULL, -- JSON array of PlateCut
    sizes TEXT NOT NULL, -- JSON array of Size
    msrp_cents INTEGER NOT NULL,
    vendor_offers TEXT NOT NULL, -- JSON array of VendorOffer
    allowed_colorways TEXT NOT NULL, -- JSON array of Colorway
    default_colorway TEXT NOT NULL -- Colorway variant name
);

CREATE TABLE IF NOT EXISTS mount_slots (
    platform_id TEXT NOT NULL REFERENCES platforms(id) ON DELETE CASCADE,
    slot_id TEXT NOT NULL,
    label TEXT NOT NULL,
    interface TEXT NOT NULL,
    anchor TEXT NOT NULL, -- JSON AnchorBox2D
    pals_cols INTEGER,
    pals_rows INTEGER,
    PRIMARY KEY (platform_id, slot_id)
);

CREATE TABLE IF NOT EXISTS components (
    id TEXT PRIMARY KEY,
    sku TEXT NOT NULL,
    name TEXT NOT NULL,
    kind TEXT NOT NULL,
    interface TEXT NOT NULL,
    anchor TEXT NOT NULL, -- JSON AnchorBox2D
    pals_cols INTEGER,
    pals_rows INTEGER,
    msrp_cents INTEGER NOT NULL,
    vendor_offers TEXT NOT NULL, -- JSON array of VendorOffer
    allowed_colorways TEXT NOT NULL, -- JSON array of Colorway
    default_colorway TEXT NOT NULL, -- Colorway variant name
    capabilities TEXT NOT NULL -- JSON array of CapabilityTag
);

CREATE TABLE IF NOT EXISTS adapter_bridges (
    id TEXT PRIMARY KEY,
    sku TEXT NOT NULL,
    name TEXT NOT NULL,
    platform_interface TEXT NOT NULL,
    component_interface TEXT NOT NULL,
    anchor TEXT NOT NULL, -- JSON AnchorBox2D
    msrp_cents INTEGER NOT NULL,
    vendor_offers TEXT NOT NULL, -- JSON array of VendorOffer
    allowed_colorways TEXT NOT NULL, -- JSON array of Colorway
    default_colorway TEXT NOT NULL -- Colorway variant name
);

CREATE TABLE IF NOT EXISTS role_presets (
    preset_id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    role TEXT, -- OperationalRole variant name, NULL for policy-only presets
    policy TEXT NOT NULL, -- RegulationPolicy variant name
    platform_sku TEXT NOT NULL,
    default_colorway TEXT NOT NULL, -- Colorway variant name
    placements TEXT NOT NULL -- JSON array of PresetPlacement
);

